import test from 'node:test';import assert from 'node:assert/strict';import {DEFAULT_DESIGN,validateDesign,safeImage} from '../../design.mjs';
test('design imports retain presentation fields and discard business/private/unknown inputs',()=>{const d=validateDesign({...DEFAULT_DESIGN,whatsappAccessToken:'private',whatsappNumber:'123',products:[{price:1}],text:{en:{hero1:'<img src=x onerror=alert(1)>',price:'₹1'},ml:{hero1:'എന്റെ ദ്വീപ്'}}});assert.equal(d.text.en.hero1,'<img src=x onerror=alert(1)>');assert.equal(d.text.ml.hero1,'എന്റെ ദ്വീപ്');assert.equal(d.text.en.price,undefined);assert.equal(d.whatsappAccessToken,undefined);assert.equal(d.products,undefined);});
test('section order permits every section once and keeps island choice visible',()=>{assert.deepEqual(validateDesign({...DEFAULT_DESIGN,order:['about','hero','explore','how'],hidden:['hero','how']}).order,['about','hero','explore','how']);for(const change of [{order:['hero','hero','how','about']},{hidden:['explore']},{order:['explore']}])assert.throws(()=>validateDesign({...DEFAULT_DESIGN,...change}));});
test('CSS, font and layout values cannot import executable or arbitrary styling',()=>{for(const change of [{colors:{accent:'red;display:none'}},{font:'url(evil)'},{radius:Infinity},{columns:5},{animations:'false'},{text:{en:{intro:'x'.repeat(1601)}}}])assert.throws(()=>validateDesign({...DEFAULT_DESIGN,...change}));});
test('images permit HTTPS and raster uploads while rejecting script/SVG/private schemes',()=>{assert.equal(safeImage('https://images.example.com/logo.png'),'https://images.example.com/logo.png');assert.equal(safeImage('data:image/png;base64,YWJj'),'data:image/png;base64,YWJj');for(const url of ['javascript:alert(1)','data:image/svg+xml;base64,YWJj','http://example.com/x','https://user:password@example.com/a','https://127.0.0.1/a','https://192.168.1.10/a','https://[::1]/a'])assert.throws(()=>safeImage(url));});
